import org.gradle.jvm.toolchain.JavaLanguageVersion
import org.gradle.jvm.toolchain.JavaToolchainService
import org.gradle.jvm.toolchain.JvmVendorSpec

// docs/sdk-reference.html, the plugin SDK reference, is generated by tools/sdk-reference/SdkReference.java from the
// guide pages in tools/sdk-reference/guide and the Javadoc of the SDK, the testkit and the bundled plugins' exported
// API packages (the "exports" of plugins/*/src/main/resources/plugin.toml):
//   sdkReference       -> rewrites docs/sdk-reference.html
//   verifySdkReference -> fails when docs/sdk-reference.html is not what those sources generate (part of :jasper-sdk:check)
// Either run also fails on an unresolved {@link}, a link to an anchor the page lacks, or a block tag written mid-line.
val referenceSdk = project(":jasper-sdk")
val referencePage = layout.projectDirectory.file("docs/sdk-reference.html")
val referenceInputs = files(
    fileTree("jasper-sdk/src/main/java"), fileTree("jasper-sdk-testkit/src/main/java"), fileTree("tools/sdk-reference"),
    fileTree("plugins") { include("*/src/main/java/dev/jasper/*/api/**", "*/src/main/resources/plugin.toml") })

fun registerSdkReference(name: String, verify: Boolean) = tasks.register(name) {
    group = if (verify) "verification" else "documentation"
    description = if (verify) "Checks that docs/sdk-reference.html is what the SDK sources and guide pages generate."
        else "Regenerates docs/sdk-reference.html from the SDK sources and guide pages."
    inputs.files(referenceInputs).withPathSensitivity(PathSensitivity.RELATIVE)
    val verified = layout.buildDirectory.file("sdk-reference/verified")
    if (verify) {
        inputs.file(referencePage).withPathSensitivity(PathSensitivity.RELATIVE)
        outputs.file(verified)
    } else {
        outputs.file(referencePage)
    }
    val launcher = referenceSdk.extensions.getByType<JavaToolchainService>().launcherFor {
        languageVersion = JavaLanguageVersion.of(25)
        vendor = JvmVendorSpec.JETBRAINS
    }
    val root = layout.projectDirectory.asFile
    doLast {
        val command = mutableListOf(launcher.get().executablePath.asFile.absolutePath,
            root.resolve("tools/sdk-reference/SdkReference.java").absolutePath, root.absolutePath, referencePage.asFile.absolutePath)
        if (verify) command += "--check"
        val process = ProcessBuilder(command).redirectErrorStream(true).start()
        val output = process.inputStream.bufferedReader().readText().trim()
        if (process.waitFor() != 0) throw GradleException(output)
        if (verify) verified.get().asFile.apply { parentFile.mkdirs(); writeText("ok\n") } else logger.lifecycle(output)
    }
}

registerSdkReference("sdkReference", verify = false)
val verifySdkReference = registerSdkReference("verifySdkReference", verify = true)
referenceSdk.tasks.named("check") { dependsOn(verifySdkReference) }
